from collections import deque
# multi-label BFS from all non-1 cells, track nearest labels counts tie
D=np.full((30,30),999); labels0=np.zeros((30,30),int); q=deque()
for r,c in zip(*np.where(grid!=1)):
 D[r,c]=0; labels0[r,c]=grid[r,c]; q.append((r,c))
# keep first propagation; BFS ordering will arbitrary, improve tie by ranking 9? let's compute exact candidate sets
cand=[[set() for _ in range(30)] for __ in range(30)]
while q:
 r,c=q.popleft()
 for rr,cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
  if 0<=rr<30 and 0<=cc<30:
   nd=D[r,c]+1
   if nd<D[rr,cc]: D[rr,cc]=nd; cand[rr][cc]={labels0[r,c]}; labels0[rr,cc]=labels0[r,c]; q.append((rr,cc))
   elif nd==D[rr,cc]: cand[rr][cc].add(labels0[r,c])
outnear=grid.copy()
for r,c in zip(*np.where(grid==1)):
 opts=cand[r][c]
 if len(opts)==1: outnear[r,c]=next(iter(opts))
 else:
  # nearest-color tie favor 6/8 if present, else 9
  ns=[grid[rr,cc] for rr,cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)) if 0<=rr<30 and 0<=cc<30 and grid[rr,cc]!=1]
  votes={v:ns.count(v) for v in opts}
  outnear[r,c]=max(opts,key=lambda v:(votes.get(v,0),v in (6,8),v==9))
print(np.sum(outnear!=grid)); print('\n'.join(' '.join(map(str,row)) for row in outnear))
